/* SystemApp: htmlview */
(function(){
  var app={
  "id": "htmlview",
  "fileName": "htmlview.xsh",
  "title": "HTML 瀏覽器",
  "description": "ExOS HTML Browser (.xsh / USER32 / sandboxed WebView2)",
  "icon": "html",
  "singleInstance": false,
  "imageFormat": "EXOS_XSH_PE_V1",
  "machine": "EXOS_IMAGE_FILE_MACHINE_V8",
  "subsystem": 2,
  "subsystemName": "IMAGE_SUBSYSTEM_WINDOWS_GUI"
};
  app.source=
      "/*EXOS_XSH_PE_V1\nMachine=EXOS_IMAGE_FILE_MACHINE_V8\nSubsystem=IMAGE_SUBSYSTEM_WINDOWS_GUI\nSubsystemVersion=1.0\nEntryPoint=main\nCharacteristics=EXECUTABLE_IMAGE|SANDBOXED\nMinimumEngine=V8\nIcon=res://shell32.dll/html\n*/\nconst comctl32=ExOS.LoadLibrary('comctl32.dll');\nconst comdlg32=ExOS.LoadLibrary('comdlg32.dll');\nconst shell32=ExOS.LoadLibrary('shell32.dll');\nconst web=ExOS.LoadLibrary('webview2.dll');\nconst uxtheme=ExOS.LoadLibrary('uxtheme.dll');\nconst dwmapi=ExOS.LoadLibrary('dwmapi.dll');\nawait comctl32.InitCommonControlsEx({classes:[comctl32.STATUSCLASSNAME]});\n\nlet path=String(process.argv[1]||'');\nconst norm=p=>String(p||'').replace(/\\//g,'\\\\');\nconst leaf=p=>{p=norm(p);const i=p.lastIndexOf('\\\\');return i>=0?p.substring(i+1):p;};\nconst parentPath=p=>{p=norm(p);const i=p.lastIndexOf('\\\\');return i>2?p.substring(0,i):'C:\\\\';};\nconst titleFromHtml=s=>{const m=/<title\\b[^>]*>([\\s\\S]*?)<\\/title\\s*>/i.exec(String(s||''));return m?String(m[1]||'').replace(/<[^>]*>/g,'').replace(/\\s+/g,' ').trim():'';};\n\nif(!path)throw new Error('沒有指定 HTML 檔案。');\npath=norm(path);\nlet source=await kernel32.ReadTextFile(path);\nlet fileName=leaf(path)||'HTML 文件';\nlet documentTitle=titleFromHtml(source);\n\nconst hwnd=await user32.CreateWindow({\n  title:'HTML 瀏覽器 - '+(documentTitle||fileName),\n  icon:'html',\n  width:1180,\n  height:780\n});\nawait uxtheme.SetWindowTheme(hwnd,'HtmlView','Browser');\nawait dwmapi.DwmSetWindowAttribute(hwnd,dwmapi.DWMWA_WINDOW_CORNER_PREFERENCE,'roundsmall');\n\nawait user32.CreateControl(hwnd,{\n  type:'div',id:'root',\n  style:{display:'flex',flexDirection:'column',width:'100%',height:'100%',minHeight:'0',margin:'0',padding:'0',overflow:'hidden',background:'#f3f4f6'}\n});\nawait user32.CreateControl(hwnd,{\n  type:'div',id:'toolbar',parentId:'root',\n  style:{display:'flex',alignItems:'center',gap:'5px',padding:'6px 7px',margin:'0',borderBottom:'1px solid #cbd5e1',background:'#f8fafc',flex:'0 0 auto'}\n});\nfor(const [id,text,title] of [\n  ['back','←','上一頁'],\n  ['forward','→','下一頁'],\n  ['reload','↻','重新整理'],\n  ['open','開啟','使用 COMDLG32 開啟 HTML 文件'],\n  ['folder','位置','在檔案總管中顯示'],\n  ['edit','編輯','編輯 HTML']\n]){\n  await user32.CreateControl(hwnd,{type:'button',id,parentId:'toolbar',text,title,style:{margin:'0',minWidth:(id==='open'||id==='folder'||id==='edit')?'54px':'34px',height:'30px',padding:'0 8px'}});\n}\nawait user32.CreateControl(hwnd,{\n  type:'input',id:'address',parentId:'toolbar',text:path,readOnly:true,\n  style:{flex:'1',height:'30px',minWidth:'120px',margin:'0',padding:'4px 9px',boxSizing:'border-box',fontFamily:'Segoe UI,Microsoft JhengHei,sans-serif',fontSize:'12px',background:'#fff'}\n});\nawait user32.CreateControl(hwnd,{\n  type:'div',id:'viewHost',parentId:'root',\n  style:{position:'relative',flex:'1',minHeight:'0',width:'100%',margin:'0',padding:'0',overflow:'hidden',background:'#fff'}\n});\nawait comctl32.CreateStatusBar(hwnd,{\n  id:'status',parentId:'root',\n  parts:[{text:'正在載入…',width:0},{text:'WebView2 沙盒',width:150},{text:'UTF-8',width:80}],\n  style:{width:'100%',margin:'0',flex:'0 0 auto'}\n});\n\nconst env=await web.CreateCoreWebView2Environment({profile:'ExOSHtmlView',networkIsolation:true});\nconst view=await web.CreateCoreWebView2Controller(env,hwnd,{hostControlId:'viewHost'});\nweb.OnEvent(view,async e=>{\n  if(!e)return;\n  if(e.action==='navigationstarting'){\n    await comctl32.StatusBar_SetText('status',0,'正在載入 '+fileName+'…');\n  }else if(e.action==='navigationcompleted'){\n    await comctl32.StatusBar_SetText('status',0,'已載入 '+fileName);\n  }\n});\n\nconst render=async reread=>{\n  try{\n    if(reread)source=await kernel32.ReadTextFile(path);\n    documentTitle=titleFromHtml(source);\n    await user32.SetWindowText(hwnd,'HTML 瀏覽器 - '+(documentTitle||fileName));\n    await user32.SetControlText('address',path);\n    await web.NavigateToString(view,source);\n  }catch(err){\n    await comctl32.StatusBar_SetText('status',0,'載入失敗');\n    await user32.MessageBox('無法顯示 HTML：\\n\\n'+String(err&&err.message?err.message:err),'HTML 瀏覽器');\n  }\n};\n\nconst chooseOpen=async()=>{\n  let initial='C:\\\\';\n  try{initial=path?parentPath(path):aw"+
      "ait kernel32.GetCurrentDirectory();}catch(ignore){}\n  return await comdlg32.GetOpenFileName({\n    hwndOwner:hwnd,\n    title:'開啟 HTML 文件',\n    initialDir:initial,\n    file:path?leaf(path):'',\n    filter:[\n      {name:'HTML 文件',pattern:'*.html;*.htm;*.xhtml'},\n      {name:'所有檔案',pattern:'*.*'}\n    ]\n  });\n};\n\nconst openHtmlFile=async()=>{\n  try{\n    const picked=await chooseOpen();\n    if(!picked||picked.ok===false)return;\n    const next=norm(picked.path||picked.file||'');\n    if(!next)return;\n    path=next;\n    fileName=leaf(path)||'HTML 文件';\n    source=await kernel32.ReadTextFile(path);\n    await render(false);\n    await comctl32.StatusBar_SetText('status',0,'已開啟 '+fileName);\n  }catch(err){\n    await comctl32.StatusBar_SetText('status',0,'開啟失敗');\n    await user32.MessageBox('無法開啟 HTML 文件：\\n\\n'+String(err&&err.message?err.message:err),'HTML 瀏覽器');\n  }\n};\n\nuser32.OnControl('back',async e=>{if(e.action!=='click')return;try{await web.GoBack(view);}catch(ignore){}});\nuser32.OnControl('forward',async e=>{if(e.action!=='click')return;try{await web.GoForward(view);}catch(ignore){}});\nuser32.OnControl('reload',async e=>{if(e.action==='click')await render(true);});\nuser32.OnControl('open',async e=>{if(e.action==='click')await openHtmlFile();});\nuser32.OnControl('folder',async e=>{if(e.action==='click')await shell32.ShellExecute(parentPath(path),'explore');});\nuser32.OnControl('edit',async e=>{if(e.action==='click')await shell32.LaunchSystemApp('html_editor',[path]);});\n\nawait render(false);\n";
  addApp("htmlview",app);
})();

