(function(){
  var app={
  "id": "image_viewer",
  "fileName": "image_viewer.xsh",
  "title": "圖片預覽",
  "description": "ExOS Image Viewer (.xsh)",
  "icon": "file",
  "singleInstance": false,
  "imageFormat": "EXOS_XSH_PE_V1",
  "machine": "EXOS_IMAGE_FILE_MACHINE_V8",
  "subsystem": 2,
  "subsystemName": "IMAGE_SUBSYSTEM_WINDOWS_GUI"
};
  app.source=
      "/*EXOS_XSH_PE_V1\nMachine=EXOS_IMAGE_FILE_MACHINE_V8\nSubsystem=IMAGE_SUBSYSTEM_WINDOWS_GUI\nSubsystemVersion=1.0\nEntryPoint=main\nCharacteristics=EXECUTABLE_IMAGE|SANDBOXED\nMinimumEngine=V8\n*/\nconst path=process.argv[1];if(!path)throw new Error('Image viewer requires a file path.');const h=await kernel32.CreateFile(path,kernel32.GENERIC_READ,kernel32.OPEN_EXISTING);const attr=await kernel32.GetFileAttributes(path);const r=await kernel32.ReadFile(h,Math.min((attr&&attr.size)||8388608,8388608),0);await kernel32.CloseHandle(h);const bytes=new Uint8Array(r.data||[]);const ext=(path.split('.').pop()||'').toLowerCase();const mime=ext==='png'?'image/png':ext==='gif'?'image/gif':ext==='webp'?'image/webp':ext==='jfif'||ext==='jpg'||ext==='jpeg'?'image/jpeg':'image/jpeg';let bin='';for(let i=0;i<bytes.length;i+=0x8000)bin+=String.fromCharCode(...bytes.subarray(i,i+0x8000));const url=`data:${mime};base64,${btoa(bin)}`;const hwnd=await user32.CreateWindow({title:'圖片預覽 - '+path.split('\\\\').pop(),icon:'file',width:900,height:680});await user32.CreateControl(hwnd,{type:'image',id:'image',src:url,alt:path,style:{display:'block',maxWidth:'100%',maxHeight:'calc(100% - 34px)',margin:'0 auto'}});await user32.CreateControl(hwnd,{type:'label',id:'info',text:`${path} ｜ ${bytes.length} bytes ｜ ${mime}`,style:{textAlign:'center',marginTop:'6px'}});";
  addApp("image_viewer",app);
})();

