/* SystemApp: nt_arch_compat_demo */
(function(){
  var app={
  "id": "nt_arch_compat_demo",
  "fileName": "nt_arch_compat_demo.xsh",
  "title": "NT 架構相容性測試",
  "description": "os84 ntoskrnl/WinUI/D3D11/OLE/Shell/ADVAPI/RichEdit semantic compatibility demo",
  "icon": "cmd",
  "singleInstance": true,
  "imageFormat": "EXOS_XSH_PE_V1",
  "machine": "EXOS_IMAGE_FILE_MACHINE_V8",
  "subsystem": 2,
  "subsystemName": "IMAGE_SUBSYSTEM_WINDOWS_GUI"
};
  app.source=
      "/*EXOS_XSH_PE_V1\nMachine=EXOS_IMAGE_FILE_MACHINE_V8\nSubsystem=IMAGE_SUBSYSTEM_WINDOWS_GUI\nSubsystemVersion=1.0\nEntryPoint=main\nCharacteristics=EXECUTABLE_IMAGE|SANDBOXED\nMinimumEngine=V8\n*/\nconst nt=ExOS.LoadLibrary('ntoskrnl.exe');\nconst winui=ExOS.LoadLibrary('winui.dll');\nconst d3d=ExOS.LoadLibrary('d3d11.dll');\nconst ole=ExOS.LoadLibrary('ole32.dll');\nconst shell=ExOS.LoadLibrary('shell32.dll');\nconst adv=ExOS.LoadLibrary('advapi32.dll');\nconst rich=ExOS.LoadLibrary('msftedit.dll');\n\nconst hwnd=await user32.CreateWindow({title:'NT Architecture Compatibility - os84',width:780,height:600});\nawait winui.Render(hwnd,{type:'div',id:'root',style:{display:'flex',flexDirection:'column',height:'100%',padding:'10px',gap:'8px'},children:[\n {type:'label',id:'title',text:'ExOS NT/Win32 semantic compatibility test',style:{fontSize:'17px',fontWeight:'600'}},\n {type:'groupbox',id:'group',text:'WinUI / RichEdit',style:{padding:'10px'},children:[\n  {type:'combobox',id:'combo',items:['NT Kernel','Shell','OLE','RichEdit'],selectedIndex:0,style:{width:'220px'}},\n  {type:'richedit',id:'rich',html:'<b>alpha</b><br>beta<br>gamma',style:{height:'120px',border:'1px solid #94a3b8',padding:'6px'}}\n ]},\n {type:'textarea',id:'log',readOnly:true,style:{flex:'1',width:'100%',fontFamily:'Consolas,monospace',fontSize:'11px'}}\n]});\n\nconst result={};\nresult.kernel=await nt.GetVersion();\nresult.time=await nt.KeQuerySystemTime();\nconst ev=await nt.KeInitializeEvent('SynchronizationEvent',false);\nawait nt.KeSetEvent(ev);\nresult.wait=await nt.KeWaitForSingleObject(ev,50);\nawait nt.NtClose(ev);\nresult.winui=await winui.QueryCapabilities();\nresult.d3d=await d3d.GetCompatibilityCaps();\nresult.guid=await ole.CoCreateGuid();\nconst stm=await ole.CreateStreamOnHGlobal();\nawait ole.StreamWrite(stm,new TextEncoder().encode('hello OLE'));\nawait ole.StreamSeek(stm,0,'SET');\nresult.stream=new TextDecoder().decode(await ole.StreamRead(stm,64));\nawait ole.ReleaseStream(stm);\nresult.desktop=await shell.SHGetKnownFolderPath('FOLDERID_DESKTOP');\nresult.documents=await shell.SHGetKnownFolderPath('FOLDERID_DOCUMENTS');\nconst tok=await adv.OpenProcessToken(-1,adv.TOKEN_QUERY);\nresult.token=await adv.GetTokenInformation(tok,adv.TokenUser);\nresult.acl=await adv.GetAclInformation([{type:'ALLOW',sid:'S-1-1-0',mask:0x80000000}]);\nresult.lines=await rich.GetLineCount('rich');\nresult.find=await rich.FindText('rich','beta',{matchCase:true});\nresult.richState=await rich.GetState('rich');\nawait winui.SetText('title','PASS - NT Architecture Compatibility');\nawait winui.SetProperty('combo','selectedIndex',2);\nawait user32.SetControlText('log',JSON.stringify(result,null,2));\nprocess.ntCompatResult=result;\n";
  addApp("nt_arch_compat_demo",app);
})();

